<script lang="ts">
 import { Heart, Minus, Plus, Truck, RotateCcw, Ruler, ArrowRight } from 'lucide-svelte'; import { products, money, colorHex } from '../lib/data/products'; import { addToCart, wishlist, toggleWishlist, notify } from '../lib/stores/commerce'; import ProductCard from '../lib/components/ProductCard.svelte';
 let { id }: {id: string} = $props(); let product = $derived(products.find(p=>p.id===id)); let selectedSize = $state(''); let quantity = $state(1); let error = $state(''); let sizeDialog = $state<HTMLDialogElement>(); let zoom = $state(false);
 $effect(()=>{id;selectedSize='';quantity=1;error='';zoom=false;});
 function add(){if(!product)return;if(!selectedSize){error='Please choose your size before adding to your bag.';return;}addToCart(product.id,selectedSize,product.color,quantity);error='';notify('Added to your bag');}
</script>
{#if product}<div class="breadcrumbs content-width"><a href="#/">Home</a><span>/</span><a href="#/shop">Collection</a><span>/</span><span>{product.name}</span></div><section class="product-detail"><div class="product-gallery"><button class="main-product-image" class:zoomed={zoom} onclick={()=>zoom=!zoom} aria-label={zoom?'Zoom out of product':'Zoom in on product'}><img src={product.image} alt={`${product.name}, full garment display without a model`}/><span>{zoom?'Click to zoom out':'Click to see the details +'}</span></button><div class="gallery-note">PRODUCT-ONLY DISPLAY · ILLUSTRATIVE DEMO IMAGE</div></div><div class="product-info"><span class="eyebrow">{product.category} · THE RAQVOI EDIT</span><h1>{product.name}</h1><div class="detail-price"><strong>{money(product.price)}</strong>{#if product.originalPrice}<s>{money(product.originalPrice)}</s><span>Save {money(product.originalPrice-product.price)}</span>{/if}</div><p class="tax-note">Demo price in INR · no payment will be collected</p><p class="product-description">{product.description}</p><div class="selection-label">Colour <strong>{product.color}</strong></div><div class="product-colour"><span style={`background:${colorHex[product.color]}`}></span><small>Shown in {product.color}</small></div><div class="selection-label">Select size <button class="inline-button" onclick={()=>sizeDialog?.showModal()}><Ruler size={14}/> Size guide</button></div><div class="size-selector">{#each product.sizes as s}<button class:selected={selectedSize===s} aria-pressed={selectedSize===s} onclick={()=>{selectedSize=s;error='';}}>{s}</button>{/each}</div>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<div class="product-purchase"><div class="quantity-control"><button aria-label="Decrease quantity" onclick={()=>quantity=Math.max(1,quantity-1)} disabled={quantity<=1}><Minus size={14}/></button><span>{quantity}</span><button aria-label="Increase quantity" onclick={()=>quantity=Math.min(10,quantity+1)} disabled={quantity>=