/tr></thead><tbody>{#each [['XS',82,66,90],['S',87,71,95],['M',92,76,100],['L',97,81,105],['XL',102,86,110],['XXL',107,91,115]] as row}<tr>{#each row as value}<td>{value}</td>{/each}</tr>{/each}</tbody></table><p>Measure around the fullest part of your bust and hips. These sample measurements are for exploring the demo.</p></dialog>{:else}<section class="empty-state"><h1>This piece couldn’t be found.</h1><a href="#/shop" class="button dark">Back to the collection</a></section>{/if}

